def find_path(graph, start, goal):
    if start is None or goal is None:
        raise ValueError("Start and goal cannot be None')

    if start not in graph:
        raise ValueError(f"Start and goal must be in the graph:  (non-empty and non-repeated)')

    if goal not in graph:
        raise ValueError(f"Start and goal must be in the graph: (non-empty and non-repeated)')

    # Initialize the stack with the starting node
    stack = [(start, [start])]     # Stack of tuples: (current node, path)

    # Traverse graph
    while stack:
        (current_node, path) = stack.pop()

        # If the current node is the goal, return the path
        if current_node == goal:
            return path

        # Explore neighbors
        for neighbor in graph[current_node]:
            if neighbor not in path:    # Avoid cycles
                stack.append((neighbor, path + [neighbor]))    # Add neighbor and full path to stack

    # If the goal is not reachable
    return None
