            visited.add(current)
            path.append(current)
            if current == goal:
                return path
            for neighbor in graph.get(current, []):
                stack.append((neighbor, path.copy()))
        return None

    # Try DFS first, and then DFS iterative
    return dfs(start, goal, []) or dfs_iterative(start, goal)
