def find_path(graph, start, goal):
    # If the start and goal are the same, we can construct a trivial path by just yielding the start (and the goal)
    if start == goal:
        return [start, goal]

    # (stack, path) - (reverse) (used in depth-first search) - (and not used here as the implementation is breadth-first search)
    from collections import deque
    visited = set()
    stack = deque([(start, [start])])

    while stack:
        (current, path) = stack.pop()  # pop() behaves like a stack, unlike deque.pop() which behaves like a queue
        visited.add(current)

        for next_node in graph[current]:
            if next_node not in visited:
                if next_node == goal:
                    return path + [next_node]
                else:
                    stack.append((next_node, path + [next_node]))

