def find_path(graph, start, goal):
    if start is None or goal is None:
        return None

    if start not in graph:
        return None

    # If the given start and goal are the same, we have one node to climb
    if (start == goal) or (not graph[start]):
        return [start]

    # Keep track of visited nodes to avoid cycles
    visited = set()
    stack = [(start, [start])]  # Each element in the stack is a tuple (current_node, path)

    while stack:
        (current_node, path) = stack.pop()
        visited.add(current_node)

        # If we reach the goal, return the path
        if current_node == goal:
            return path
        # Explore the neighbors
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                stack.append((neighbor, path + [neighbor]))

    # If we exhaust all neighbors without finding the goal, return None
    return None
