def find_path(graph, start, goal):
    # A simple recursive (and a bit non-optimistic) deep-first search (DFS) with a stack
    if start == goal:
        return [start]  # If we are trying to find a non-empty path from the goal to itself, we found it.

    visited = set()
    path_stack = [(start, [start])]  # A stack storing tuples of (current node, current path)

    while path_stack:
        (current_node, current_path) = path_stack.pop()
        for next_node in graph[current_node]:
            if next_node not in visited:
                path_stack.append((next_node, current_path + [next_node]))
                if next_node == goal:
                    return current_path + [next_node]  # Return the path found
        visited.add(current_node)
    return None  # Goal is not reachable
